def main():
    app=load(APP_ASSET); patch=load(PATCH_ASSET)
    if app!=patch: raise SystemExit('app/patch differ before batch9')
    by={s['id']:s for s in app['scenarios']}
    for sid,route in ROUTES.items():
        s=by[sid]; apply_route(s,**route)
        s.setdefault('actions',[{}])[0].update({'sourceBound':False,'riskClass':'normal','userFacingPolicy':'TRIAGE_ONLY_NO_REPAIR'})
        s['sourceAudit']={'auditedAt':V,'scope':'p0_recuperation_batch9','status':'IMPROVE'}
        addref(s,R1); addref(s,LEGACY); old_historical(s)
        if sid in {'ER-DIAG-057','ER-DIAG-058','ER-DIAG-062'}:
            addref(s,R2); addref(s,R8)
        if sid in {'ER-DIAG-059','ER-DIAG-060','ER-DIAG-064'}:
            addref(s,BRAKES); addref(s,R3508)
        s['sourceAgeNote']='Повторный аудит 26.09.2026: только раннее base_early исполнение. РЭ1/РЭ2/РЭ8 используются как техническая база схемы; старые памятки — только symptom cross-check. Уставки SP2/SP3 и обозначение реле защиты возбуждения profile-dependent. Действующие с 01.07.2026 тормозные Правила применяются отдельно от заводских уставок.'
    if len(app['scenarios'])!=136: raise SystemExit('scenario count changed')
    dump(APP_ASSET,app); dump(PATCH_ASSET,app)
    if APP_ASSET.read_bytes()!=PATCH_ASSET.read_bytes(): raise SystemExit('app/patch mismatch')
    print('ERMAK_P0_RECUPERATION_BATCH9='+','.join(sorted(ROUTES)))

if __name__=='__main__': main()
